/**
 * Codegen: engine catalog → TypeScript modules.
 *
 * Reads `engine/catalog.snapshot.json` (generated by the Rust engine)
 * and produces per-file directory structures:
 *
 *   - `src/generated/catalog/` - per-type node info + per-processor definitions
 *   - `src/generated/schemas/` - per-processor Zod schemas
 *   - `src/generated/engineSchemaEntries.ts` - auto-assembled NODE_SCHEMAS + NODE_PARAM_FIELDS
 *   - `src/generated/definitionSchema.ts` - JSON Schema for `.bnto.json` files
 *   - `src/generated/formatVersion.ts` - catalog version string
 *   - `packages/@bnto/backend/convex/_helpers/nodeTypeLabels.ts` - label map for Convex
 *   - `packages/@bnto/i18n/src/generated/nodes.json` - i18n strings
 *
 * Adding a new node type produces NEW per-type files + append-only barrel updates.
 * No monolithic files to regenerate, no merge conflicts.
 *
 * The Rust engine is the single source of truth for ALL node metadata.
 * Each output's generator lives in `codegen/`; this file runs them in order.
 * Run via: `task nodes:generate` or `npx tsx scripts/generate-from-catalog.ts`
 */

import { writeCatalogFiles } from "./codegen/catalog/writeCatalogFiles";
import { createWriter } from "./codegen/createWriter";
import { writeNodeReadmes } from "./codegen/docs/writeNodeReadmes";
import { recipesFile } from "./codegen/files/recipesFile";
import { RECIPES_OUTPUT } from "./codegen/paths";
import { printSummary } from "./codegen/printSummary";
import { readCatalog } from "./codegen/readCatalog";
import { removeLegacyFiles } from "./codegen/removeLegacyFiles";
import { writeSchemaFiles } from "./codegen/schemas/writeSchemaFiles";
import { writeGeneratedModules } from "./codegen/writeGeneratedModules";

const catalog = readCatalog();
const out = createWriter();

writeCatalogFiles(out, catalog);
writeSchemaFiles(out, catalog);
writeGeneratedModules(out, catalog);
writeNodeReadmes(catalog);

const recipes = recipesFile(catalog);
if (recipes) out.write(RECIPES_OUTPUT, recipes);

removeLegacyFiles();
printSummary(out, catalog);
